using System;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Windows.Forms;
namespace Frociart.Tests {internal static class FunctionLibraryTests {
 static int checks;static void Check(bool v,string why){if(!v)throw new Exception(why);checks++;Console.WriteLine("PASS "+why);}
 static void Pump(){var until=DateTime.UtcNow.AddMilliseconds(300);do{Application.DoEvents();Thread.Sleep(5);}while(DateTime.UtcNow<until);}
 static void Shot(Form f,string name){string dir=Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"library");Directory.CreateDirectory(dir);using(var bmp=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bmp,new Rectangle(Point.Empty,bmp.Size));bmp.Save(Path.Combine(dir,name+".png"));}}
 static void Prepare(Form f){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-3000,-2500);f.ShowInTaskbar=false;f.Show();Pump();}
 static void VerifyAllCards(){foreach(bool dark in new[]{false,true}){Ui.SetDarkMode(dark,false);using(var dialog=new FunctionLibraryDialog()){dialog.Size=dialog.MinimumSize;Prepare(dialog);for(int i=0;i<dialog.Results.Items.Count;i++){dialog.Results.SelectedIndex=i;Pump();Size required=dialog.Details.GetPreferredSize(new Size(dialog.Details.Width,0));Check(required.Height<=dialog.Details.Height,"Full explanation fits at minimum size: "+dialog.Results.Items[i]+" required="+required.Height+" available="+dialog.Details.Height);}dialog.Search.Text="vettore(dimensione";Shot(dialog,dark?"longest-dark-minimum":"longest-light-minimum");dialog.Close();}}}
 [STAThread]public static int Main(){try{Application.EnableVisualStyles();VerifyAllCards();
 foreach(bool dark in new[]{false,true}){Ui.SetDarkMode(dark,false);using(var d=new FunctionLibraryDialog()){Prepare(d);Check(d.Results.Items.Count==35,"All 30 function cards and 5 operator cards visible");d.Search.Text="radice";Check(d.Results.Items.Count==1&&d.Details.Text.Contains("sqrt(9)"),"Search by everyday description");d.Search.Text="nothingMatchesHere";Check(d.Results.Items.Count==0&&!d.Insert.Enabled&&d.Details.Text.Contains("Nessuna"),"Empty search is recoverable");d.Search.Text="TOFIXED";Check(d.Results.Items.Count==1&&d.Details.Text.Contains("12.50"),"Case-insensitive search and actual result");d.Size=d.MinimumSize;Pump();Check(d.Insert.Visible&&d.Details.Bottom<d.ClientSize.Height,"Description and action at minimum size");Shot(d,dark?"dark-minimum":"light-minimum");d.Search.Text="";d.Size=new Size(720,670);Pump();Shot(d,dark?"dark":"light");d.Search.Text="radice";d.Insert.PerformClick();Check(d.SelectedExample=="sqrt(9)"&&d.DialogResult==DialogResult.OK,"Choice returns executable example");}}
 using(var owner=new Form()){var target=new TextBox{Text="totale = 0 + 1",MaxLength=100};owner.Controls.Add(target);Prepare(owner);target.Select(9,1);Exception timerError=null;using(var timer=new System.Windows.Forms.Timer()){timer.Interval=50;timer.Tick+=delegate{var dialog=Application.OpenForms.OfType<FunctionLibraryDialog>().FirstOrDefault();if(dialog==null)return;timer.Stop();try{dialog.Search.Text="radice";dialog.Insert.PerformClick();}catch(Exception e){timerError=e;dialog.Close();}};timer.Start();FunctionLibraryDialog.InsertInto(owner,target);}if(timerError!=null)throw timerError;Check(target.Text=="totale = sqrt(9) + 1","Inserts at selection and preserves surrounding text");owner.Close();}
 using(var f=new MainForm(null,true)){Prepare(f);f.SetDocument(FlowPseudocode.Decode("x = 0\nSTAMPA x"),null,false);f.EnterEditor();var operation=f.Document.Nodes.First(n=>n.Kind==NodeKind.Process);f.Canvas.SelectNode(operation.Id);Pump();var field=f.GetType().GetField("functionButton",BindingFlags.NonPublic|BindingFlags.Instance);var button=(Control)field.GetValue(f);Check(button.Visible&&button.Text.Contains("Funzioni"),"Catalog accessible from actual block editor");f.Canvas.SelectNode(f.Document.Nodes.First(n=>n.Kind==NodeKind.Start).Id);Check(!button.Visible,"No expression tools on start/end labels");f.SetDocument(new Diagram(),null,false);f.Close();}
 Console.WriteLine("FUNCTION_LIBRARY_PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}}
